import fs from 'fs';
import fsPromises from 'fs/promises';
import path from 'path';
import { createLogger } from '../utils/logger';

const log = createLogger('PreviewEnvironment');

export class PreviewEnvironment {
  private readonly overlays = new Map<string, Set<string>>();

  async prepare(args: {
    projectPath: string;
    worktreePath: string;
    cwd: string;
  }): Promise<void> {
    const { projectPath, worktreePath, cwd } = args;
    for (const file of this.overlays.get(worktreePath) ?? []) {
      await fsPromises.rm(file, { force: true });
    }
    const overlaid = new Set<string>();
    this.overlays.set(worktreePath, overlaid);
    const hostRoot = resolveHostRoot(projectPath, cwd);
    const roots: Array<{ host: string; target: string }> = [
      { host: hostRoot, target: worktreePath },
    ];
    if (cwd !== '.' && cwd !== '') {
      roots.push({
        host: path.resolve(hostRoot, cwd),
        target: path.resolve(worktreePath, cwd),
      });
    }
    for (const { host, target } of roots) {
      if (!fs.existsSync(host) || !fs.existsSync(target)) continue;
      let entries: string[];
      try {
        entries = await fsPromises.readdir(host);
      } catch {
        continue;
      }
      for (const entry of entries) {
        if (entry === '.env' || entry.startsWith('.env.')) {
          const dest = path.join(target, entry);
          if (!fs.existsSync(dest)) {
            await fsPromises
              .copyFile(path.join(host, entry), dest)
              .then(() => {
                overlaid.add(dest);
              })
              .catch((err) =>
                log.warn(`overlay: .env copy failed for ${dest}`, err),
              );
          }
        }
      }
    }
  }

  forget(worktreePath: string): void {
    this.overlays.delete(worktreePath);
  }
}

const resolveHostRoot = (projectPath: string, cwd: string): string => {
  if (cwd === '.' || cwd === '') return projectPath;
  const normalized = path.resolve(projectPath);
  const suffix = path.join(path.sep, path.normalize(cwd));
  return normalized.endsWith(suffix)
    ? normalized.slice(0, normalized.length - suffix.length)
    : normalized;
};
